#include <BLEDevice.h>
#include <BLEServer.h>
#include <BLEUtils.h>

void setup() {
  Serial.begin(115200);
  BLEDevice::init("{{device_name}}");
  BLEServer* server = BLEDevice::createServer();
  BLEService* svc = server->createService("{{service_uuid}}");
  BLECharacteristic* ch = svc->createCharacteristic("{{char_uuid}}", BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_WRITE);
  ch->setValue("hello");
  svc->start();
  BLEAdvertising* adv = BLEDevice::getAdvertising();
  adv->addServiceUUID("{{service_uuid}}");
  adv->start();
}

void loop() { delay(2000); }
